<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
try{installed();Auth::load();SaasLegacyBoundary::enforce();$r=Google::callback($_GET);$target=$r['return_to']??'settings';if($target==='clients')$url=base('clientes?drive_connected='.(int)$r['account_id']);elseif($target==='agenda')$url=base('agenda?google_connected=1');else $url=base('configuracoes?google_connected='.(int)$r['account_id'].'&purpose='.rawurlencode((string)$r['purpose']));header('Location: '.$url);exit;}catch(AppError $e){http_response_code($e->status);echo '<!doctype html><meta charset="utf-8"><style>body{font:16px system-ui;background:#050505;color:#f5f5f5;padding:35px}a{color:#fff}</style><h1>Não foi possível conectar</h1><p>'.e($e->getMessage()).'</p><a href="configuracoes">Voltar</a>';}catch(Throwable $e){error_log((string)$e);http_response_code(500);echo 'Falha ao conectar a conta Google.';}
